 1	final class FloydWarshallSolver {
 2	    private static final String OVERFLOW_MESSAGE = "Path distance overflowed int range.";
 3	
 4	    private final int[][] distances;
 5	    private final int vertexCount;
 6	
 7	    private FloydWarshallSolver(int[][] graph) {
 8	        vertexCount = MatrixValidator.requireSquare(graph, "Graph matrix");
 9	        distances = MatrixUtils.copyOf(graph);
10	    }
11	
12	    static int[][] solve(int[][] graph) {
13	        return new FloydWarshallSolver(graph).solve();
14	    }
15	
16	    private int[][] solve() {
17	        for (int via = 0; via < vertexCount; via++) {
18	            relaxPathsVia(via);
19	        }
20	
21	        return distances;
22	    }
23	
24	    private void relaxPathsVia(int via) {
25	        int[] viaRow = distances[via];
26	        for (int[] fromRow : distances) {
27	            relaxRow(fromRow, viaRow, via);
28	        }
29	    }
30	
31	    private void relaxRow(int[] fromRow, int[] viaRow, int via) {
32	        int distanceToVia = fromRow[via];
33	        if (!FloydWarshall.isReachable(distanceToVia)) {
34	            return;
35	        }
36	
37	        for (int to = 0; to < fromRow.length; to++) {
38	            relaxDistance(fromRow, viaRow, distanceToVia, to);
39	        }
40	    }
41	
42	    private void relaxDistance(int[] fromRow, int[] viaRow, int distanceToVia, int to) {
43	        int distanceFromVia = viaRow[to];
44	        if (!FloydWarshall.isReachable(distanceFromVia)) {
45	            return;
46	        }
47	
48	        int candidateDistance = addDistances(distanceToVia, distanceFromVia);
49	        if (candidateDistance < fromRow[to]) {
50	            fromRow[to] = candidateDistance;
51	        }
52	    }
53	
54	    private int addDistances(int left, int right) {
55	        try {
56	            return Math.addExact(left, right);
57	        } catch (ArithmeticException exception) {
58	            throw new ArithmeticException(OVERFLOW_MESSAGE);
59	        }
60	    }
61	}

