 3	final class MatrixUtils {
 4	    private MatrixUtils() {
 5	    }
 6	
 7	    static int[][] copyOf(int[][] matrix) {
 8	        MatrixValidator.requireRectangular(matrix, "Matrix");
 9	        return copyRows(matrix);
10	    }
11	
12	    static int[][] copyRows(int[][] matrix) {
13	        if (matrix == null) {
14	            throw new IllegalArgumentException("Matrix must not be null.");
15	        }
16	
17	        int[][] copy = new int[matrix.length][];
18	        for (int rowIndex = 0; rowIndex < matrix.length; rowIndex++) {
19	            int[] row = matrix[rowIndex];
20	            copy[rowIndex] = row == null ? null : Arrays.copyOf(row, row.length);
21	        }
22	
23	        return copy;
24	    }
25	
26	    static boolean hasNegativeDiagonalEntry(int[][] matrix) {
27	        for (int index = 0; index < matrix.length; index++) {
28	            if (matrix[index][index] < 0) {
29	                return true;
30	            }
31	        }
32	
33	        return false;
34	    }
35	}
